def _make_case_class(metadata: dict, class_name: str):
    class GeneratedATSIExecutableCase(A2AExecutableCase):
        def __init__(self) -> None:
            super().__init__(metadata)

    GeneratedATSIExecutableCase.__name__ = class_name
    GeneratedATSIExecutableCase.__qualname__ = class_name
    return GeneratedATSIExecutableCase


for _index, _metadata in enumerate(CASE_METADATA, start=1):
    if _metadata.get('is_control'):
        _class_name = f"ATSIControl{_index - 100:03d}"
    else:
        _class_name = f"ATSIEval{_index:03d}"
    globals()[_class_name] = _make_case_class(_metadata, _class_name)

